<script setup>
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { Html5Qrcode } from 'html5-qrcode'
import QRCode from 'qrcode'
import * as XLSX from 'xlsx'
import { Home, ScanLine, ClipboardList, FileCheck2, Users, QrCode, Settings, LogOut, Bell, Search, CalendarDays, CheckCircle2, Clock3, AlertCircle, Menu, X, Camera, Upload, Download, ShieldCheck, ChevronDown, Plus, RefreshCw } from 'lucide-vue-next'

const role = ref('student')
const loggedIn = ref(false)
const loginRole = ref('student')
const loginUser = ref('0123456789')
const loginPassword = ref('demo123')
const loginError = ref('')
const page = ref('dashboard')
const studentName = ref('Yasir Asyafii')
const studentId = ref('0123456789')
const adminName = 'Sekretaris XII-B'
const students = ref(JSON.parse(localStorage.getItem('sipresensi_students') || 'null') || [
 {name:'Muhammad Yasir Asyafii',nisn:'0123456789',present:22,permit:2,late:1},
 {name:'Alya Putri Ramadhani',nisn:'0123456781',present:23,permit:1,late:0},
 {name:'Rizky Maulana',nisn:'0123456782',present:21,permit:2,late:2},
 {name:'Nadia Azzahra',nisn:'0123456783',present:24,permit:0,late:0},
 {name:'Fahri Akbar',nisn:'0123456784',present:20,permit:3,late:1},
 {name:'Siti Nurhaliza',nisn:'0123456785',present:23,permit:1,late:0},
 {name:'Dimas Saputra',nisn:'0123456786',present:22,permit:1,late:1},
 {name:'Putri Amelia',nisn:'0123456787',present:24,permit:0,late:0}
])
const attendance = ref(JSON.parse(localStorage.getItem('sipresensi_attendance') || '[]'))
const permits = ref(JSON.parse(localStorage.getItem('sipresensi_permits') || '[]'))
const activeSession = ref(JSON.parse(localStorage.getItem('sipresensi_session') || 'null'))
const schedule = ['07.00','09.00','11.00','13.00','15.00']
const currentDate = new Date().toLocaleDateString('id-ID',{weekday:'long',day:'numeric',month:'long',year:'numeric'})
const qrData = ref('')
const qrImage = ref('')
const selectedSlot = ref(schedule[0])
const scanning = ref(false)
const scannerMessage = ref('')
const scanner = ref(null)
const dispReason = ref('Sakit')
const dispSession = ref('Sesi 1 — 07.00')
const dispNote = ref('')
const dispPhoto = ref(null)
const dispPhotoName = ref('')
const allDayReason = ref('Sakit')
const allDayStart = ref(new Date().toISOString().slice(0,10))
const allDayEnd = ref(new Date().toISOString().slice(0,10))
const allDayNote = ref('')
const allDayPhoto = ref(null)
const allDayPhotoName = ref('')
const search = ref('')
const showAdd = ref(false)
const newName = ref('')
const newNisn = ref('')
const period = ref('Semester 1')
const menuOpen = ref(false)
const photoItems = ref(JSON.parse(localStorage.getItem('sipresensi_photos_meta') || '[]'))
const photoFilter = ref('Semua')
const photoProcessing = ref(false)
const attendanceRows = ref(JSON.parse(localStorage.getItem('sipresensi_photo_rows') || '[]'))
const selectedPhotoIds = ref([])
const photoPreview = ref(null)
const photoUrls = ref({})
const rowMonth = ref('Semua')
const showAddPhotoRow = ref(false)
const newRowDate = ref(new Date().toISOString().slice(0,10))
const newRowStudent = ref('')
const newRowStatuses = ref(Array(10).fill('H'))
const months = ['September 2026','Oktober 2026','November 2026']
const photoStats = computed(()=>({total:photoItems.value.length,ready:photoItems.value.filter(p=>p.status==='Menunggu OCR').length,review:attendanceRows.value.filter(r=>r.review).length,processed:photoItems.value.filter(p=>p.status==='Selesai').length}))
const filteredPhotoItems = computed(()=>photoItems.value.filter(p=>photoFilter.value==='Semua'||p.status===photoFilter.value))
const filteredPhotoRows = computed(()=>attendanceRows.value.filter(r=>rowMonth.value==='Semua'||monthLabel(r.date)===rowMonth.value))
const currentStudent = computed(()=>students.value.find(s=>s.nisn===studentId.value) || students.value[0])
const studentRecords = computed(()=>attendance.value.filter(a=>a.nisn===studentId.value))
const presentCount = computed(()=>studentRecords.value.filter(a=>a.status==='Hadir').length)
const totalSessions = computed(()=>Math.max(25, presentCount.value + studentRecords.value.filter(a=>a.status!=='Hadir').length))
const attendancePercent = computed(()=>Math.round((currentStudent.value?.present||22)/Math.max(1,(currentStudent.value?.present||22)+(currentStudent.value?.permit||0)+(currentStudent.value?.late||0))*100))
const filteredStudents = computed(()=>students.value.filter(s=>s.name.toLowerCase().includes(search.value.toLowerCase())||s.nisn.includes(search.value)))
const pendingPermits = computed(()=>permits.value.filter(p=>p.status==='Menunggu'))
const navStudent = [{id:'dashboard',label:'Dashboard',icon:Home},{id:'scanner',label:'Scan Absensi',icon:ScanLine},{id:'history',label:'Riwayat',icon:ClipboardList},{id:'permit',label:'Dispen per Sesi',icon:FileCheck2},{id:'allDayPermit',label:'Izin Seharian',icon:CalendarDays}]
const navAdmin = [{id:'dashboard',label:'Dashboard',icon:Home},{id:'students',label:'Data Siswa',icon:Users},{id:'qr',label:'QR Absensi',icon:QrCode},{id:'recap',label:'Rekapitulasi',icon:ClipboardList},{id:'photoRecap',label:'Rekap Foto',icon:Camera},{id:'permits',label:'Verifikasi Dispen',icon:FileCheck2},{id:'settings',label:'Pengaturan',icon:Settings}]
function save(){localStorage.setItem('sipresensi_students',JSON.stringify(students.value));localStorage.setItem('sipresensi_attendance',JSON.stringify(attendance.value));localStorage.setItem('sipresensi_permits',JSON.stringify(permits.value));localStorage.setItem('sipresensi_session',JSON.stringify(activeSession.value));localStorage.setItem('sipresensi_photos_meta',JSON.stringify(photoItems.value));localStorage.setItem('sipresensi_photo_rows',JSON.stringify(attendanceRows.value))}
function monthLabel(date){const d=new Date(date+'T00:00:00');return d.toLocaleDateString('id-ID',{month:'long',year:'numeric'})}
function openPhotoRecap(){page.value='photoRecap'}
function initPhotoDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open('SIPRESENSI_Photos',1);req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains('photos'))db.createObjectStore('photos',{keyPath:'id'})};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)}); }
async function putPhotoBlob(id,blob){const db=await initPhotoDB();return new Promise((resolve,reject)=>{const tx=db.transaction('photos','readwrite');tx.objectStore('photos').put({id,blob});tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>{db.close();reject(tx.error)}})}
async function getPhotoBlob(id){const db=await initPhotoDB();return new Promise((resolve,reject)=>{const tx=db.transaction('photos','readonly');const req=tx.objectStore('photos').get(id);req.onsuccess=()=>{db.close();resolve(req.result?.blob||null)};req.onerror=()=>{db.close();reject(req.error)}})}
async function deletePhotoBlob(id){const db=await initPhotoDB();return new Promise((resolve,reject)=>{const tx=db.transaction('photos','readwrite');tx.objectStore('photos').delete(id);tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>{db.close();reject(tx.error)}})}
async function handlePhotoUpload(event){const files=[...(event.target.files||[])];event.target.value='';if(!files.length)return;photoProcessing.value=true;for(const file of files){if(!['image/jpeg','image/png','image/webp','application/pdf'].includes(file.type)){continue}const id=`photo-${Date.now()}-${Math.random().toString(36).slice(2,7)}`;const item={id,name:file.name,type:file.type,size:file.size,date:new Date().toISOString(),status:'Menunggu OCR',duplicate:false};if(photoItems.value.some(p=>p.name===file.name&&p.size===file.size)){item.duplicate=true;item.status='Duplikat mungkin'};try{await putPhotoBlob(id,file);photoItems.value.unshift(item);if(file.type.startsWith('image/'))photoUrls.value[id]=URL.createObjectURL(file)}catch(e){alert('Gagal menyimpan file '+file.name+' pada penyimpanan browser.')}}photoProcessing.value=false;save()}
async function showPhoto(item){closePhotoPreview();const blob=await getPhotoBlob(item.id);if(blob){photoPreview.value={item,url:URL.createObjectURL(blob)}}}
async function loadPhotoThumbs(){for(const item of photoItems.value){if(item.type?.startsWith('image/')&&!photoUrls.value[item.id]){const blob=await getPhotoBlob(item.id);if(blob)photoUrls.value[item.id]=URL.createObjectURL(blob)}}}
function closePhotoPreview(){if(photoPreview.value?.url)URL.revokeObjectURL(photoPreview.value.url);photoPreview.value=null}
async function removePhoto(id){if(!confirm('Hapus foto ini dari SIPRESENSI?'))return;await deletePhotoBlob(id);if(photoUrls.value[id])URL.revokeObjectURL(photoUrls.value[id]);delete photoUrls.value[id];photoItems.value=photoItems.value.filter(p=>p.id!==id);selectedPhotoIds.value=selectedPhotoIds.value.filter(x=>x!==id);save()}
async function removeSelectedPhotos(){if(!selectedPhotoIds.value.length)return;if(!confirm(`Hapus ${selectedPhotoIds.value.length} foto terpilih?`))return;for(const id of selectedPhotoIds.value){await deletePhotoBlob(id);if(photoUrls.value[id])URL.revokeObjectURL(photoUrls.value[id]);delete photoUrls.value[id]}photoItems.value=photoItems.value.filter(p=>!selectedPhotoIds.value.includes(p.id));selectedPhotoIds.value=[];save()}
async function clearPhotoData(){if(!confirm('Hapus seluruh foto dan data rekap foto? Tindakan ini tidak dapat dibatalkan.'))return;for(const item of photoItems.value){await deletePhotoBlob(item.id);if(photoUrls.value[item.id])URL.revokeObjectURL(photoUrls.value[item.id])}photoUrls.value={};photoItems.value=[];attendanceRows.value=[];selectedPhotoIds.value=[];save()}
function addManualPhotoRow(){if(!newRowStudent.value||!newRowDate.value)return;const student=students.value.find(s=>s.nisn===newRowStudent.value);attendanceRows.value.unshift({id:Date.now(),date:newRowDate.value,nisn:student?.nisn||'',name:student?.name||newRowStudent.value,statuses:[...newRowStatuses.value],review:newRowStatuses.value.includes('?'),source:'Input manual'});newRowStudent.value='';newRowStatuses.value=Array(10).fill('H');showAddPhotoRow.value=false;save()}
function updateRowStatus(row,index,value){row.statuses[index]=value;row.review=false;save()}
function removeRow(id){if(!confirm('Hapus baris rekap ini?'))return;attendanceRows.value=attendanceRows.value.filter(r=>r.id!==id);save()}
function exportPhotoExcel(){const wb=XLSX.utils.book_new();for(const month of months){const rows=attendanceRows.value.filter(r=>monthLabel(r.date)===month).sort((a,b)=>a.date.localeCompare(b.date));const data=[['Tanggal','Hari','No. Absen','Nama Siswa',...Array.from({length:10},(_,i)=>`Jam ${i+1}`),'Hadir','Sakit','Rekomendasi','Izin'],...rows.map(r=>{const st=r.statuses||Array(10).fill('H');return [r.date,new Date(r.date+'T00:00:00').toLocaleDateString('id-ID',{weekday:'long'}),students.value.findIndex(s=>s.nisn===r.nisn)+1,r.name,...st,st.filter(x=>x==='H').length,st.filter(x=>x==='S').length,st.filter(x=>x==='R').length,st.filter(x=>x==='I').length]})];const ws=XLSX.utils.aoa_to_sheet(data);ws['!autofilter']={ref:`A1:${XLSX.utils.encode_col(data[0].length-1)}${data.length}`};ws['!views']=[{state:'frozen',xSplit:4,ySplit:1}];ws['!cols']=[{wch:13},{wch:14},{wch:10},{wch:28},...Array(10).fill({wch:8}),...Array(4).fill({wch:14})];XLSX.utils.book_append_sheet(wb,ws,month.slice(0,31))}const summary=[['No. Absen','Nama','Hadir','Sakit','Rekomendasi','Izin','Total Jam'],...students.value.map((s,i)=>{const own=attendanceRows.value.filter(r=>r.nisn===s.nisn);const statuses=own.flatMap(r=>r.statuses||[]);return [i+1,s.name,statuses.filter(x=>x==='H').length,statuses.filter(x=>x==='S').length,statuses.filter(x=>x==='R').length,statuses.filter(x=>x==='I').length,statuses.length]})];XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(summary),'Rekap Seluruh Siswa');const review=[['Tanggal','No. Absen','Nama','Jam','Status','Sumber'],...attendanceRows.value.filter(r=>r.review).flatMap(r=>(r.statuses||[]).map((s,i)=>s==='?'?[r.date,students.value.findIndex(x=>x.nisn===r.nisn)+1,r.name,i+1,s,r.source||'']:[]).filter(Boolean))];XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(review),'Perlu Ditinjau');XLSX.writeFile(wb,'SIPRESENSI-Rekap-Foto-XII-B.xlsx')}
function clearMonthRows(month){if(!confirm(`Hapus seluruh rekap bulan ${month}?`))return;attendanceRows.value=attendanceRows.value.filter(r=>monthLabel(r.date)!==month);save()}
function switchRole(r){role.value=r;page.value='dashboard';stopScan()}
function login(){loginError.value='';if(loginRole.value==='admin'){if(loginUser.value.toLowerCase()!=='sekretaris'||loginPassword.value!=='admin123'){loginError.value='Username atau password sekretaris salah.';return}role.value='admin'}else{const student=students.value.find(s=>s.nisn===loginUser.value);if(!student||loginPassword.value!=='demo123'){loginError.value='NISN atau password siswa salah. Akun demo menggunakan password demo123.';return}studentId.value=student.nisn;studentName.value=student.name;role.value='student'}loggedIn.value=true;page.value='dashboard';localStorage.setItem('sipresensi_demo_login',JSON.stringify({role:role.value,studentId:studentId.value}))}
function logout(){loggedIn.value=false;page.value='dashboard';loginError.value='';stopScan();localStorage.removeItem('sipresensi_demo_login')}
function makeSession(){const token='SIPRESENSI-XIIB-'+Date.now()+'-'+Math.random().toString(36).slice(2,9).toUpperCase();activeSession.value={token,session:selectedSlot.value,created:new Date().toISOString(),status:'Aktif'};qrData.value=token;QRCode.toDataURL(token,{width:280,margin:2,color:{dark:'#16263d',light:'#ffffff'}}).then(v=>qrImage.value=v);save()}
function createSessionFor(slot){selectedSlot.value=slot}
async function startScan(){if(scanning.value)return;scannerMessage.value='';scanning.value=true;await new Promise(r=>setTimeout(r,100));try{scanner.value=new Html5Qrcode('qr-reader');await scanner.value.start({facingMode:'environment'},{fps:10,qrbox:{width:230,height:230}},onScan,()=>{})}catch(e){scannerMessage='Kamera tidak dapat dibuka. Pastikan izin kamera aktif atau gunakan demo scan.';scanning.value=false}}
function onScan(decoded){if(!activeSession.value||decoded!==activeSession.value.token){scannerMessage='QR tidak valid atau sesi sudah berubah.';return}if(attendance.value.some(a=>a.nisn===studentId.value&&a.session===activeSession.value.session)){scannerMessage='Kamu sudah absen pada sesi ini.';stopScan();return}attendance.value.push({nisn:studentId.value,name:studentName.value,session:activeSession.value.session,date:new Date().toISOString(),status:'Hadir'});currentStudent.value.present++;save();scannerMessage='Absensi berhasil tercatat!';stopScan()}
async function stopScan(){if(scanner.value){try{await scanner.value.stop();await scanner.value.clear()}catch{}scanner.value=null}scanning.value=false}
function demoScan(){if(!activeSession.value){scannerMessage='Admin belum membuat QR aktif.';return}onScan(activeSession.value.token)}
function uploadPhoto(e){const f=e.target.files?.[0];if(!f)return;dispPhoto.value=f;dispPhotoName.value=f.name}
function submitPermit(){if(!dispPhoto.value){alert('Mohon unggah foto bukti terlebih dahulu.');return}const reader=new FileReader();reader.onload=()=>{permits.value.unshift({id:Date.now(),scope:'session',name:studentName.value,nisn:studentId.value,reason:dispReason.value,session:dispSession.value,note:dispNote.value,photo:reader.result,photoName:dispPhotoName.value,status:'Menunggu',created:new Date().toISOString()});save();dispPhoto.value=null;dispPhotoName.value='';dispNote.value='';page.value='history';alert('Pengajuan dispen terkirim!')};reader.readAsDataURL(dispPhoto.value)}
function submitAllDayPermit(){if(!allDayStart.value||!allDayEnd.value||allDayEnd.value<allDayStart.value){alert('Periksa tanggal izin.');return}if(allDayReason.value==='Sakit'&&!allDayPhoto.value){alert('Untuk izin sakit, bukti foto wajib diunggah.');return}const create=(photo)=>{permits.value.unshift({id:Date.now(),scope:'all-day',name:studentName.value,nisn:studentId.value,reason:allDayReason.value,startDate:allDayStart.value,endDate:allDayEnd.value,session:'Sehari penuh',note:allDayNote.value,photo:photo||null,photoName:allDayPhotoName.value||'',status:'Menunggu',created:new Date().toISOString()});save();allDayPhoto.value=null;allDayPhotoName.value='';allDayNote.value='';page.value='history';alert('Pengajuan izin sehari penuh terkirim. Menunggu verifikasi sekretaris.')};if(allDayPhoto.value){const reader=new FileReader();reader.onload=()=>create(reader.result);reader.readAsDataURL(allDayPhoto.value)}else create(null)}
function decidePermit(id,status){const p=permits.value.find(x=>x.id===id);if(!p)return;p.status=status;if(status==='Disetujui'&&p.scope==='all-day'){const start=new Date(p.startDate+'T12:00:00Z');const end=new Date(p.endDate+'T12:00:00Z');for(let d=new Date(start);d<=end;d.setUTCDate(d.getUTCDate()+1)){const dateStr=d.toISOString().slice(0,10);for(const time of schedule){if(!attendance.value.some(a=>a.nisn===p.nisn&&a.session===time&&a.date?.slice(0,10)===dateStr)){attendance.value.push({nisn:p.nisn,name:p.name,session:time,date:dateStr+'T00:00:00',status:p.reason==='Sakit'?'Sakit':'Izin'})}}}}save()}
function openProof(photo){if(photo)window.open(photo,'_blank')}
function addStudent(){if(!newName.value.trim()||!newNisn.value.trim())return;students.value.push({name:newName.value.trim(),nisn:newNisn.value.trim(),present:0,permit:0,late:0});newName.value='';newNisn.value='';showAdd.value=false;save()}
function downloadCSV(){const rows=[['Nama','NISN','Hadir','Izin','Terlambat','Persentase'],...students.value.map(s=>[s.name,s.nisn,s.present,s.permit,s.late,Math.round(s.present/Math.max(1,s.present+s.permit+s.late)*100)+'%'])];const csv=rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\n');const blob=new Blob([csv],{type:'text/csv'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='rekap-SIPRESENSI-XII-B.csv';a.click();URL.revokeObjectURL(url)}
onMounted(()=>{const session=JSON.parse(localStorage.getItem('sipresensi_demo_login')||'null');if(session){loggedIn.value=true;role.value=session.role;if(session.studentId){studentId.value=session.studentId;studentName.value=students.value.find(s=>s.nisn===session.studentId)?.name||studentName.value}}if(activeSession.value){qrData.value=activeSession.value.token;QRCode.toDataURL(activeSession.value.token,{width:280,margin:2}).then(v=>qrImage.value=v)};initPhotoDB().then(loadPhotoThumbs).catch(()=>{})})
onUnmounted(()=>{stopScan();closePhotoPreview();Object.values(photoUrls.value).forEach(u=>URL.revokeObjectURL(u))})
</script>

<template>
<template v-if="!loggedIn"><div class="login-screen"><div class="login-card"><div class="login-brand"><div class="brand-mark"><ScanLine :size="24"/></div><div><b>SIPRESENSI</b><small>Digital Attendance • XII-B</small></div></div><h1>Selamat datang 👋</h1><p>Masuk untuk mengakses absensi kelas.</p><form class="form login-form" @submit.prevent="login"><label>Login sebagai<select v-model="loginRole" @change="loginUser=loginRole==='admin'?'sekretaris':'0123456789';loginPassword=loginRole==='admin'?'admin123':'demo123'"><option value="student">Siswa</option><option value="admin">Sekretaris kelas</option></select></label><label>{{loginRole==='student'?'NISN':'Username'}}<input v-model="loginUser" :placeholder="loginRole==='student'?'Masukkan NISN':'Username sekretaris'" required/></label><label>Password<input type="password" v-model="loginPassword" placeholder="Masukkan password" required/></label><div v-if="loginError" class="login-error">{{loginError}}</div><button class="primary-button full" type="submit">Masuk</button></form><div class="demo-credentials"><b>Akun demo frontend</b><span>Siswa: NISN 0123456789 • Password demo123</span><span>Sekretaris: sekretaris • Password admin123</span><small>Login ini simulasi frontend, belum autentikasi backend.</small></div></div></div></template><div v-else class="app-shell">
 <aside class="sidebar" :class="{'mobile-open':menuOpen}">
  <div class="brand"><div class="brand-mark"><ScanLine :size="22"/></div><div><b>SIPRESENSI</b><small>Digital Attendance</small></div><button class="close-menu" @click="menuOpen=false"><X/></button></div>
  <div class="class-pill"><span class="dot"></span> KELAS XII-B</div>
  <div class="nav-label">MENU UTAMA</div>
  <button v-for="item in (role==='student'?navStudent:navAdmin)" :key="item.id" class="nav-item" :class="{active:page===item.id}" @click="page=item.id;menuOpen=false"><component :is="item.icon" :size="18"/><span>{{item.label}}</span><span v-if="item.id==='permits'&&pendingPermits.length" class="nav-count">{{pendingPermits.length}}</span></button>
  <div class="sidebar-bottom"><div class="help-card"><div class="help-icon"><ShieldCheck :size="18"/></div><b>Absensi lebih mudah</b><p>Pastikan akunmu hanya digunakan di perangkat pribadi.</p></div><button class="nav-item" @click="logout"><LogOut :size="18"/><span>Keluar akun</span></button></div>
 </aside>
 <main class="main-area">
  <header class="topbar"><button class="menu-button" @click="menuOpen=true"><Menu/></button><div class="crumb"><span>Workspace</span><b>/</b><strong>{{pageTitle || page}}</strong></div><div class="top-actions"><button class="icon-button"><Bell :size="18"/><i></i></button><div class="profile"><div class="avatar">{{role==='student'?'YA':'SB'}}</div><div class="profile-text"><b>{{role==='student'?studentName:adminName}}</b><small>{{role==='student'?'Siswa XII-B':'Admin Kelas'}}</small></div><ChevronDown :size="16"/></div></div></header>
  <div class="content">
   <div class="demo-switch"><span><strong>Mode Demo</strong> — login frontend simulasi • kelas XII-B</span></div>
   <template v-if="role==='student'&&page==='dashboard'">
    <div class="page-heading"><div><h1>Halo, {{studentName.split(' ')[0]}}! 👋</h1><p>Semoga harimu produktif. Yuk cek kehadiranmu hari ini.</p></div><div class="date-chip"><CalendarDays :size="16"/> {{currentDate}}</div></div>
    <div class="stats-grid student-stats"><div class="stat-card"><div class="stat-top"><span class="stat-icon blue"><CheckCircle2/></span><span class="trend">Semester ini</span></div><div class="stat-value">{{attendancePercent}}<small>%</small></div><div class="stat-label">Persentase Kehadiran</div><div class="progress"><span :style="{width:attendancePercent+'%'}"></span></div></div><div class="stat-card"><div class="stat-top"><span class="stat-icon green"><ClipboardList/></span></div><div class="stat-value">{{currentStudent.present}}</div><div class="stat-label">Total Hadir</div><small class="muted">Dari rekap yang tercatat</small></div><div class="stat-card"><div class="stat-top"><span class="stat-icon orange"><Clock3/></span></div><div class="stat-value">{{currentStudent.late}}</div><div class="stat-label">Terlambat</div><small class="muted">Perlu diperhatikan</small></div><div class="stat-card"><div class="stat-top"><span class="stat-icon purple"><FileCheck2/></span></div><div class="stat-value">{{currentStudent.permit}}</div><div class="stat-label">Izin / Dispen</div><small class="muted">Pengajuan dispen tercatat</small></div></div>
    <div class="two-col"><section class="panel"><div class="panel-head"><div><h3>Jadwal Absensi Hari Ini</h3><p>Absensi dilakukan setiap 2 jam pelajaran</p></div><span class="badge neutral">5 sesi</span></div><div class="session-list"><div v-for="(time,i) in schedule" :key="time" class="session-row"><div class="session-num">{{i+1}}</div><div class="session-info"><b>Sesi {{i+1}}</b><small>{{time}} WIB</small></div><span class="session-status" :class="attendance.some(a=>a.nisn===studentId&&a.session===time)?'done':'waiting'">{{attendance.some(a=>a.nisn===studentId&&a.session===time)?'Hadir':'Belum absen'}}</span></div></div><button class="primary-button full" @click="page='scanner'"><ScanLine :size="17"/> Buka Scanner Absensi</button></section><section class="panel"><div class="panel-head"><div><h3>Ringkasan Kehadiran</h3><p>Periode {{period}}</p></div><button class="text-button" @click="page='history'">Lihat riwayat <span>→</span></button></div><div class="attendance-ring"><div class="ring" :style="{'--percent':attendancePercent+'%'}"><div><strong>{{attendancePercent}}%</strong><small>kehadiran</small></div></div></div><div class="legend"><span><i class="green-dot"></i>Hadir <b>{{currentStudent.present}}</b></span><span><i class="orange-dot"></i>Izin <b>{{currentStudent.permit}}</b></span><span><i class="red-dot"></i>Absen <b>0</b></span></div><div class="notice"><AlertCircle :size="17"/><span>Jika berhalangan hadir, ajukan dispen dan sertakan bukti foto.</span></div></section></div>
   </template>
   <template v-else-if="role==='student'&&page==='scanner'">
    <div class="page-heading"><div><h1>Scan Absensi</h1><p>Scan QR yang ditampilkan sekretaris kelas untuk mencatat kehadiran.</p></div></div><div class="scanner-layout"><section class="panel scanner-panel"><div class="scanner-frame"><div id="qr-reader"></div><div v-if="!scanning" class="scanner-placeholder"><div class="camera-icon"><Camera :size="34"/></div><b>Kamera scanner siap</b><p>Tekan tombol di bawah untuk mulai memindai QR.</p></div></div><div class="scanner-actions"><button class="primary-button" @click="startScan" :disabled="scanning"><Camera :size="17"/> {{scanning?'Scanner aktif':'Mulai scan'}}</button><button class="secondary-button" @click="demoScan"><ScanLine :size="17"/> Demo scan</button><button v-if="scanning" class="secondary-button" @click="stopScan">Stop</button></div><div v-if="scannerMessage" class="scanner-message" :class="scannerMessage.includes('berhasil')?'success':''">{{scannerMessage}}</div></section><section class="panel scan-info"><h3>Petunjuk</h3><ol><li>Pastikan kamu sudah login dengan akun sendiri.</li><li>Izinkan akses kamera browser.</li><li>Arahkan kamera ke QR sesi aktif.</li><li>Pastikan notifikasi berhasil muncul.</li></ol><div class="notice"><Clock3 :size="17"/><span>Jam masuk 07.00 dengan toleransi 20 menit. Jika lewat, hubungi sekretaris/guru.</span></div><div class="active-qr"><span class="dot" :class="activeSession?'':'gray'"></span><div><b>{{activeSession?'Sesi QR tersedia':'Belum ada QR aktif'}}</b><small>{{activeSession?'QR sedang aktif dibuat admin':'Tunggu sekretaris membuat QR'}}</small></div></div></section></div>
   </template>
   <template v-else-if="role==='student'&&page==='permit'">
    <div class="page-heading"><div><h1>Dispen / Izin</h1><p>Ajukan izin jika tidak dapat mengikuti sesi absensi.</p></div></div><div class="two-col permit-layout"><section class="panel"><div class="panel-head"><div><h3>Form Pengajuan</h3><p>Semua pengajuan wajib menyertakan bukti foto.</p></div></div><form @submit.prevent="submitPermit" class="form"><label>Jenis izin<select v-model="dispReason"><option>Sakit</option><option>Keperluan keluarga</option><option>Kegiatan sekolah</option><option>Lainnya</option></select></label><label>Sesi yang diajukan<select v-model="dispSession"><option v-for="(t,i) in schedule" :key="t">Sesi {{i+1}} — {{t}}</option></select></label><label>Keterangan<textarea v-model="dispNote" rows="3" placeholder="Tambahkan keterangan (opsional)"></textarea></label><label class="upload-box"><Upload/><b>Upload foto bukti</b><small>JPG, PNG (maks. 5 MB)</small><input type="file" accept="image/*" @change="uploadPhoto"/><span v-if="dispPhotoName" class="uploaded">{{dispPhotoName}}</span></label><button class="primary-button full" type="submit">Kirim Pengajuan</button></form></section><section class="panel"><h3>Ketentuan Dispen</h3><div class="rule-list"><div><CheckCircle2 class="green-text"/><span>Bukti foto harus jelas dan dapat diperiksa.</span></div><div><AlertCircle class="orange-text"/><span>Jika bukti buram atau diragukan, admin akan meminta konfirmasi.</span></div><div><Clock3/><span>Pengajuan akan diproses sekretaris kelas.</span></div></div><div class="notice"><ShieldCheck/><span>Data dan bukti digunakan untuk keperluan administrasi absensi XII-B.</span></div></section></div>
   </template>
   <template v-else-if="role==='student'&&page==='allDayPermit'">
    <div class="page-heading"><div><h1>Izin Seharian</h1><p>Ajukan izin satu atau beberapa hari tanpa mengisi absensi per jam.</p></div></div><div class="two-col permit-layout"><section class="panel"><div class="panel-head"><div><h3>Pengajuan Izin Penuh</h3><p>Pengajuan mencakup seluruh 10 jam pelajaran pada tanggal yang dipilih.</p></div></div><form class="form" @submit.prevent="submitAllDayPermit"><label>Jenis izin<select v-model="allDayReason"><option>Sakit</option><option>Keperluan keluarga</option><option>Lainnya</option></select></label><div class="two-col date-fields"><label>Tanggal mulai<input type="date" v-model="allDayStart" required/></label><label>Tanggal selesai<input type="date" v-model="allDayEnd" :min="allDayStart" required/></label></div><label>Keterangan<textarea v-model="allDayNote" rows="3" placeholder="Keterangan tambahan (opsional)"></textarea></label><label class="upload-box"><Upload/><b>Upload bukti foto {{allDayReason==='Sakit'?'(wajib)':'(opsional)'}}</b><small>JPG, PNG</small><input type="file" accept="image/*" @change="e=>{allDayPhoto=e.target.files?.[0]||null;allDayPhotoName=allDayPhoto?.name||''}"/><span v-if="allDayPhotoName" class="uploaded">{{allDayPhotoName}}</span></label><div class="notice"><AlertCircle/><span>Jika disetujui, seluruh 10 jam pada tanggal izin akan otomatis tercatat sebagai {{allDayReason==='Sakit'?'Sakit':'Izin'}}.</span></div><button class="primary-button full" type="submit">Kirim Pengajuan Izin</button></form></section><section class="panel"><h3>Alur izin</h3><div class="rule-list"><div><CheckCircle2 class="green-text"/><span>Pilih tanggal atau rentang tanggal.</span></div><div><CheckCircle2 class="green-text"/><span>Sakit wajib melampirkan bukti foto.</span></div><div><Clock3/><span>Sekretaris memeriksa atau meminta konfirmasi.</span></div><div><ShieldCheck/><span>Setelah disetujui, seluruh sesi otomatis dicatat.</span></div></div></section></div>
   </template>
   <template v-else-if="role==='student'&&page==='history'">
    <div class="page-heading"><div><h1>Riwayat Absensi</h1><p>Riwayat kehadiran dan pengajuan dispenmu.</p></div></div><section class="panel"><div class="panel-head"><h3>Riwayat Sesi</h3><span class="badge neutral">{{studentRecords.length}} catatan</span></div><div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Sesi</th><th>Status</th></tr></thead><tbody><tr v-for="a in studentRecords" :key="a.date"><td>{{new Date(a.date).toLocaleDateString('id-ID')}}</td><td>{{a.session}}</td><td><span class="badge" :class="a.status==='Hadir'?'success':a.status==='Sakit'?'warning':'neutral'">{{a.status}}</span></td></tr><tr v-if="!studentRecords.length"><td colspan="3" class="empty">Belum ada catatan scan yang tersimpan.</td></tr></tbody></table></div></section><section class="panel mt"><div class="panel-head"><h3>Riwayat Dispen</h3></div><div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Alasan</th><th>Sesi</th><th>Status</th></tr></thead><tbody><tr v-for="p in permits.filter(x=>x.nisn===studentId)" :key="p.id"><td>{{new Date(p.created).toLocaleDateString('id-ID')}}</td><td>{{p.reason}}</td><td>{{p.scope==='all-day'?p.startDate+' s/d '+p.endDate:p.session}}</td><td><span class="badge" :class="p.status==='Disetujui'?'success':p.status==='Ditolak'?'danger':'warning'">{{p.status}}</span></td></tr><tr v-if="!permits.some(x=>x.nisn===studentId)"><td colspan="4" class="empty">Belum ada pengajuan dispen.</td></tr></tbody></table></div></section>
   </template>
   <template v-else-if="role==='admin'&&page==='dashboard'">
    <div class="page-heading"><div><h1>Dashboard XII-B</h1><p>Ringkasan aktivitas absensi kelas hari ini.</p></div><div class="date-chip"><CalendarDays :size="16"/> {{currentDate}}</div></div><div class="stats-grid"><div class="stat-card"><div class="stat-top"><span class="stat-icon blue"><Users/></span></div><div class="stat-value">{{students.length}}</div><div class="stat-label">Total Siswa</div></div><div class="stat-card"><div class="stat-top"><span class="stat-icon green"><CheckCircle2/></span></div><div class="stat-value">{{students.reduce((n,s)=>n+s.present,0)}}</div><div class="stat-label">Total Kehadiran Tercatat</div></div><div class="stat-card"><div class="stat-top"><span class="stat-icon orange"><FileCheck2/></span></div><div class="stat-value">{{pendingPermits.length}}</div><div class="stat-label">Dispen Menunggu</div></div><div class="stat-card"><div class="stat-top"><span class="stat-icon purple"><QrCode/></span></div><div class="stat-value">{{activeSession?'Aktif':'—'}}</div><div class="stat-label">QR Absensi</div><small class="muted">{{activeSession?'Sesi '+activeSession.session:'Belum dibuat'}}</small></div></div><div class="two-col admin-dash"><section class="panel"><div class="panel-head"><div><h3>Dashboard Kehadiran</h3><p>Rekap ringkas per siswa</p></div><button class="text-button" @click="page='recap'">Lihat rekap →</button></div><div class="table-wrap"><table><thead><tr><th>Siswa</th><th>Hadir</th><th>Persentase</th></tr></thead><tbody><tr v-for="s in students.slice(0,5)" :key="s.nisn"><td><div class="person-cell"><div class="avatar small">{{s.name.slice(0,1)}}</div>{{s.name}}</div></td><td>{{s.present}}</td><td><div class="mini-progress"><span :style="{width:Math.round(s.present/Math.max(1,s.present+s.permit+s.late)*100)+'%'}"></span></div>{{Math.round(s.present/Math.max(1,s.present+s.permit+s.late)*100)}}%</td></tr></tbody></table></div></section><section class="panel"><div class="panel-head"><div><h3>Pengajuan Dispen</h3><p>Perlu pemeriksaan</p></div><span class="badge warning">{{pendingPermits.length}} pending</span></div><div v-if="pendingPermits.length" class="permit-mini" v-for="p in pendingPermits.slice(0,3)" :key="p.id"><div class="avatar small">{{p.name.slice(0,1)}}</div><div class="mini-info"><b>{{p.name}}</b><small>{{p.reason}} • {{p.scope==='all-day'?p.startDate+' s/d '+p.endDate:p.session}}</small></div><button class="text-button" @click="page='permits'">Review</button></div><div v-else class="empty">Tidak ada pengajuan yang menunggu.</div><button class="secondary-button full mt-sm" @click="page='permits'">Buka Verifikasi</button></section></div>
   </template>
   <template v-else-if="role==='admin'&&page==='students'">
    <div class="page-heading"><div><h1>Data Siswa</h1><p>Kelola data akun siswa kelas XII-B.</p></div><button class="primary-button" @click="showAdd=true"><Plus/> Tambah Siswa</button></div><section class="panel"><div class="panel-head"><div><h3>Daftar Siswa</h3><p>{{students.length}} siswa terdaftar</p></div><div class="search-box"><Search/><input v-model="search" placeholder="Cari nama atau NISN"/></div></div><div class="table-wrap"><table><thead><tr><th>Nama Siswa</th><th>NISN</th><th>Hadir</th><th>Izin</th><th>Terlambat</th><th>Kehadiran</th></tr></thead><tbody><tr v-for="s in filteredStudents" :key="s.nisn"><td><div class="person-cell"><div class="avatar small">{{s.name.slice(0,1)}}</div><b>{{s.name}}</b></div></td><td>{{s.nisn}}</td><td>{{s.present}}</td><td>{{s.permit}}</td><td>{{s.late}}</td><td>{{Math.round(s.present/Math.max(1,s.present+s.permit+s.late)*100)}}%</td></tr></tbody></table></div></section>
   </template>
   <template v-else-if="role==='admin'&&page==='qr'">
    <div class="page-heading"><div><h1>QR Absensi Universal</h1><p>Buat QR acak untuk sesi absensi kelas. QR baru akan menggantikan QR sebelumnya.</p></div></div><div class="two-col qr-layout"><section class="panel qr-maker"><div class="panel-head"><div><h3>Generator QR</h3><p>Pilih sesi, lalu buat kode absensi.</p></div><span class="badge success" v-if="activeSession">Aktif</span></div><div class="session-picker"><label>Pilih sesi absensi<select v-model="selectedSlot" @change="createSessionFor(selectedSlot)"><option v-for="t in schedule" :key="t" :value="t">Sesi {{schedule.indexOf(t)+1}} — {{t}}</option></select></label><button class="primary-button full" @click="makeSession"><RefreshCw/> Generate QR Acak</button></div><div class="qr-display" v-if="qrImage"><img :src="qrImage" alt="QR Absensi"/><b>Sesi {{schedule.indexOf(activeSession.session)+1}} — {{activeSession.session}}</b><small>Token: {{activeSession.token.slice(-12)}}</small><button class="secondary-button" @click="makeSession"><RefreshCw/> Refresh QR</button></div><div v-else class="qr-empty"><QrCode/><b>QR belum dibuat</b><small>Generate QR untuk memulai sesi absensi.</small></div></section><section class="panel"><h3>Informasi Sesi</h3><div class="info-table"><div><span>Hari / tanggal</span><b>{{currentDate}}</b></div><div><span>Jadwal</span><b>5 sesi / hari</b></div><div><span>Interval</span><b>Setiap 2 jam pelajaran</b></div><div><span>Toleransi</span><b>20 menit dari 07.00</b></div><div><span>QR</span><b>Token acak, satu sesi aktif</b></div></div><div class="notice"><AlertCircle/><span>Prototype ini belum memvalidasi token melalui server, jadi jangan gunakan untuk absensi resmi sebelum backend dipasang.</span></div></section></div>
   </template>
   <template v-else-if="role==='admin'&&page==='recap'">
    <div class="page-heading"><div><h1>Rekapitulasi Absensi</h1><p>Rekap kelas XII-B berdasarkan periode.</p></div><button class="secondary-button" @click="downloadCSV"><Download/> Export CSV</button></div><section class="panel"><div class="panel-head"><div><h3>Rekap Siswa</h3><p>Perhitungan dari data demo yang tersimpan di perangkat ini.</p></div><select class="period-select" v-model="period"><option>Semester 1</option><option>Semester 2</option><option>Triwulan 1</option><option>Triwulan 2</option><option>Triwulan 3</option><option>Triwulan 4</option></select></div><div class="table-wrap"><table><thead><tr><th>Nama</th><th>NISN</th><th>Hadir</th><th>Izin</th><th>Terlambat</th><th>Persentase</th><th>Evaluasi</th></tr></thead><tbody><tr v-for="s in students" :key="s.nisn"><td><b>{{s.name}}</b></td><td>{{s.nisn}}</td><td>{{s.present}}</td><td>{{s.permit}}</td><td>{{s.late}}</td><td>{{Math.round(s.present/Math.max(1,s.present+s.permit+s.late)*100)}}%</td><td><span class="badge" :class="s.present/Math.max(1,s.present+s.permit+s.late)>=.9?'success':'warning'">{{s.present/Math.max(1,s.present+s.permit+s.late)>=.9?'Baik':'Perlu perhatian'}}</span></td></tr></tbody></table></div></section>
   </template>
   <template v-else-if="role==='admin'&&page==='photoRecap'">
    <div class="page-heading"><div><h1>Rekap Absensi Berbasis Foto</h1><p>Upload dan kelola foto buku absensi. OCR belum terhubung pada tahap frontend ini.</p></div><div class="photo-heading-actions"><button class="secondary-button" @click="exportPhotoExcel"><Download/> Export Excel</button><button class="danger-button" @click="clearPhotoData"><X/> Hapus Semua</button></div></div>
    <div class="stats-grid"><div class="stat-card"><div class="stat-top"><span class="stat-icon blue"><Camera/></span></div><div class="stat-value">{{photoStats.total}}</div><div class="stat-label">Foto tersimpan</div></div><div class="stat-card"><div class="stat-top"><span class="stat-icon orange"><Clock3/></span></div><div class="stat-value">{{photoStats.ready}}</div><div class="stat-label">Menunggu OCR</div></div><div class="stat-card"><div class="stat-top"><span class="stat-icon green"><CheckCircle2/></span></div><div class="stat-value">{{photoStats.processed}}</div><div class="stat-label">Sudah diproses</div></div><div class="stat-card"><div class="stat-top"><span class="stat-icon purple"><AlertCircle/></span></div><div class="stat-value">{{photoStats.review}}</div><div class="stat-label">Perlu ditinjau</div></div></div>
    <section class="panel photo-upload-panel"><div class="panel-head"><div><h3>Upload Foto Buku Absensi</h3><p>Pilih beberapa foto sekaligus. File disimpan di browser menggunakan IndexedDB.</p></div><span class="badge neutral">Frontend • OCR belum aktif</span></div><label class="photo-drop"><Upload/><b>Pilih foto atau PDF</b><small>JPG, JPEG, PNG, WebP, PDF • Upload massal</small><input type="file" accept="image/jpeg,image/png,image/webp,application/pdf" multiple @change="handlePhotoUpload"/></label><div v-if="photoProcessing" class="notice"><Clock3/><span>Menyimpan file ke penyimpanan lokal…</span></div></section>
    <section class="panel mt"><div class="panel-head"><div><h3>Daftar Foto</h3><p>{{photoItems.length}} file • dapat dipilih dan dihapus</p></div><div class="photo-tools"><select v-model="photoFilter"><option>Semua</option><option>Menunggu OCR</option><option>Duplikat mungkin</option><option>Selesai</option></select><button class="danger-button" :disabled="!selectedPhotoIds.length" @click="removeSelectedPhotos">Hapus Terpilih ({{selectedPhotoIds.length}})</button></div></div><div v-if="photoItems.length" class="photo-file-grid"><article class="photo-file" v-for="item in filteredPhotoItems" :key="item.id"><label class="photo-check"><input type="checkbox" v-model="selectedPhotoIds" :value="item.id"/></label><div class="photo-thumb" @click="showPhoto(item)"><Camera v-if="item.type==='application/pdf'"/><img v-else-if="photoUrls[item.id]" :src="photoUrls[item.id]" alt="thumbnail"/><span>{{item.type==='application/pdf'?'PDF':'GAMBAR'}}</span></div><div class="photo-file-info"><b :title="item.name">{{item.name}}</b><small>{{(item.size/1024).toFixed(0)}} KB • {{new Date(item.date).toLocaleDateString('id-ID')}}</small><span class="badge" :class="item.duplicate?'warning':'neutral'">{{item.status}}</span></div><div class="photo-file-actions"><button class="text-button" @click="showPhoto(item)">Preview</button><button class="danger-button compact" @click="removePhoto(item.id)">Hapus</button></div></article></div><div v-else class="empty-state"><Camera/><b>Belum ada foto</b><p>Upload dokumentasi buku absensi untuk memulai.</p></div></section>
    <section class="panel mt"><div class="panel-head"><div><h3>Data Rekap Manual / Hasil OCR</h3><p>Data dapat diedit. Input manual aktif sementara sebelum integrasi OCR.</p></div><div class="photo-tools"><select v-model="rowMonth"><option>Semua</option><option v-for="m in months" :key="m">{{m}}</option></select><button class="primary-button" @click="showAddPhotoRow=true"><Plus/> Tambah Baris</button></div></div><div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>No.</th><th>Nama Siswa</th><th v-for="n in 10" :key="n">JP {{n}}</th><th>H</th><th>S</th><th>R</th><th>I</th><th>Aksi</th></tr></thead><tbody><tr v-for="r in filteredPhotoRows" :key="r.id"><td>{{r.date}}</td><td>{{students.findIndex(s=>s.nisn===r.nisn)+1||'—'}}</td><td>{{r.name}}</td><td v-for="(status,i) in r.statuses" :key="i"><select class="status-cell" :value="status" @change="updateRowStatus(r,i,$event.target.value)"><option>H</option><option>S</option><option>R</option><option>I</option><option>?</option></select></td><td>{{r.statuses.filter(x=>x==='H').length}}</td><td>{{r.statuses.filter(x=>x==='S').length}}</td><td>{{r.statuses.filter(x=>x==='R').length}}</td><td>{{r.statuses.filter(x=>x==='I').length}}</td><td><button class="danger-button compact" @click="removeRow(r.id)">Hapus</button></td></tr></tbody></table></div><div v-if="rowMonth!=='Semua'" class="panel-foot"><button class="danger-button" @click="clearMonthRows(rowMonth)">Hapus Rekap {{rowMonth}}</button></div><div v-if="!filteredPhotoRows.length" class="empty">Belum ada data rekap. Gunakan Tambah Baris untuk menguji rekap manual.</div></section>
    <div class="notice"><AlertCircle/><span>OCR/AI Vision belum terintegrasi. Foto yang diunggah belum otomatis dibaca; status menunggu OCR ditampilkan dengan jujur. Semua file dan baris rekap disimpan secara lokal pada browser ini.</span></div>
   </template>
   <template v-else-if="role==='admin'&&page==='permits'">
    <div class="page-heading"><div><h1>Verifikasi Dispen</h1><p>Periksa foto bukti dan konfirmasi pengajuan siswa.</p></div><span class="badge warning">{{pendingPermits.length}} menunggu</span></div><section class="panel"><div v-if="permits.length" class="permit-list"><article v-for="p in permits" :key="p.id" class="permit-card"><div class="permit-top"><div class="person-cell"><div class="avatar">{{p.name.slice(0,1)}}</div><div><b>{{p.name}}</b><small>{{p.reason}} • {{p.scope==='all-day'?p.startDate+' s/d '+p.endDate:p.session}}</small></div></div><span class="badge" :class="p.status==='Disetujui'?'success':p.status==='Ditolak'?'danger':'warning'">{{p.status}}</span></div><p class="permit-note">{{p.scope==='all-day'?'Izin penuh: seluruh sesi pada rentang tanggal.':'Izin hanya untuk sesi yang dipilih.'}} {{p.note||'Tidak ada keterangan tambahan.'}}</p><div v-if="p.photo" class="proof"><img :src="p.photo" alt="Bukti dispen"/><div><b>{{p.photoName}}</b><small>Foto bukti yang dilampirkan</small><button class="text-button" @click="openProof(p.photo)">Lihat foto</button></div></div><div v-else class="notice"><AlertCircle/><span>Pengajuan ini tidak menyertakan foto bukti.</span></div><div v-if="p.status==='Menunggu'" class="permit-actions"><button class="primary-button" @click="decidePermit(p.id,'Disetujui')"><CheckCircle2/> Setujui</button><button class="secondary-button" @click="decidePermit(p.id,'Perlu Konfirmasi')"><AlertCircle/> Minta Konfirmasi</button><button class="danger-button" @click="decidePermit(p.id,'Ditolak')">Tolak</button></div></article></div><div v-else class="empty-state"><FileCheck2/><b>Belum ada pengajuan dispen</b><p>Pengajuan dari siswa akan muncul di sini.</p></div></section>
   </template>
   <template v-else-if="role==='admin'&&page==='settings'">
    <div class="page-heading"><div><h1>Pengaturan</h1><p>Pengaturan periode dan aturan kelas.</p></div></div><section class="panel settings-panel"><h3>Periode Absensi</h3><label>Periode rekap<select v-model="period"><option>Semester 1</option><option>Semester 2</option><option>Triwulan 1</option><option>Triwulan 2</option><option>Triwulan 3</option><option>Triwulan 4</option></select></label><div class="info-table"><div><span>Kelas</span><b>XII-B</b></div><div><span>Jam mulai</span><b>07.00</b></div><div><span>Toleransi masuk</span><b>20 menit</b></div><div><span>Jumlah sesi</span><b>5 sesi (10 JP)</b></div><div><span>Interval sesi</span><b>2 jam pelajaran</b></div></div><div class="notice"><AlertCircle/><span>Pengaturan tahun pelajaran dan jadwal otomatis perlu backend/database untuk tersimpan secara konsisten bagi seluruh perangkat.</span></div></section>
   </template>
   <div v-if="showAddPhotoRow" class="modal-overlay" @click.self="showAddPhotoRow=false"><div class="modal photo-row-modal"><div class="modal-head"><h3>Tambah Rekap Manual</h3><button class="icon-button" @click="showAddPhotoRow=false"><X/></button></div><form class="form" @submit.prevent="addManualPhotoRow"><label>Tanggal<input type="date" v-model="newRowDate" required/></label><label>Siswa<select v-model="newRowStudent" required><option value="" disabled>Pilih siswa</option><option v-for="s in students" :key="s.nisn" :value="s.nisn">{{s.name}}</option></select></label><div class="status-edit-grid"><label v-for="(st,i) in newRowStatuses" :key="i">JP {{i+1}}<select v-model="newRowStatuses[i]"><option>H</option><option>S</option><option>R</option><option>I</option><option>?</option></select></label></div><button class="primary-button full" type="submit">Simpan Rekap</button></form></div></div>
   <div v-if="photoPreview" class="modal-overlay" @click.self="closePhotoPreview"><div class="modal photo-preview-modal"><div class="modal-head"><h3>{{photoPreview.item.name}}</h3><button class="icon-button" @click="closePhotoPreview"><X/></button></div><div class="photo-preview-content"><iframe v-if="photoPreview.item.type==='application/pdf'" :src="photoPreview.url" title="Preview PDF"></iframe><img v-else :src="photoPreview.url" alt="Foto absensi preview"/></div></div></div>
   <div v-if="showAdd" class="modal-overlay" @click.self="showAdd=false"><div class="modal"><div class="modal-head"><h3>Tambah Siswa</h3><button class="icon-button" @click="showAdd=false"><X/></button></div><form @submit.prevent="addStudent" class="form"><label>Nama lengkap<input v-model="newName" required placeholder="Nama siswa"/></label><label>NISN<input v-model="newNisn" required placeholder="Nomor NISN"/></label><button class="primary-button full" type="submit">Simpan Siswa</button></form></div></div>
  </div>
 </main>
</div>
</template>
