export default {computed:{pageTitle(){const map={dashboard:'Dashboard',scanner:'Scan Absensi',history:'Riwayat',permit:'Dispen per Sesi',allDayPermit:'Izin Seharian',students:'Data Siswa',qr:'QR Absensi',recap:'Rekapitulasi',permits:'Verifikasi Dispen',settings:'Pengaturan',photoRecap:'Rekap Foto Absensi'};return map[this.page]}}}
